def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    opp_d_total = sum(1 for a in opp_actions if a == 'D')
    my_d_total = sum(1 for a in my_actions if a == 'D')

    if opp_d_total == 0:
        if my_d_total == 0:
            if n >= 10 and n < 90 and n % 10 == 0:
                return 'D'
            return 'C'
        else:
            opp_forgiveness = 0
            for i in range(1, n):
                if history[i-1][0] == 'D' and history[i][1] == 'C':
                    opp_forgiveness = 1
                    break
            if opp_forgiveness:
                return 'D'
            else:
                return 'C'

    opp_d_rate = opp_d_total / n
    recent = history[-10:] if n >= 10 else history
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_my_d = sum(1 for a, b in recent if a == 'D')
    last_me, last_opp = history[-1]

    if opp_d_rate > 0.6 or recent_opp_d >= 7:
        return 'D'
    if opp_d_rate > 0.4 or recent_opp_d >= 4:
        return 'D'

    if recent_my_d >= 3 and recent_opp_d >= 1:
        return 'C'

    my_d_last3 = sum(1 for a in my_actions[-3:] if a == 'D') if n >= 3 else sum(1 for a in my_actions if a == 'D')

    if opp_d_rate < 0.2 and recent_opp_d <= 2:
        if last_opp == 'D':
            if last_me == 'C':
                if my_d_last3 > 0:
                    return 'C'
                else:
                    return 'D'
            else:
                return 'C'
        else:
            return 'C'

    if last_opp == 'D':
        if my_d_last3 > 0:
            return 'C'
        return 'D'
    else:
        if opp_d_rate < 0.3 and recent_my_d == 0 and n > 20:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    return 'C'
